#!/bin/bash
# Rebuild the images in site/img/ from source.
#
#   site/tools/make-site-images.sh [brand|phones|all]
#
# Two groups:
#
#   brand   og-cartworth.png, icon-180.png, cartworth-logo.png
#           Finished artwork. og-cartworth.svg is authored here; the two icons
#           are resampled from the built app icon, so the site and the app ship
#           the same mark by construction.
#
#   phones  iphone-max-search.png, iphone-max-deal.png, iphone-max-trip.png,
#           iphone-duo.png
#           ILLUSTRATIONS of the app, generated by make-phone-svg.py. They are
#           not screenshots, and the header comment in that file explains at
#           length why the real captures in marketing/screenshots/ could not be
#           used and what index.html has to say about these as a result.
#
# Pipeline notes, all of which are worked around rather than fixed:
#
#   * qlmanage is the only SVG rasteriser on this machine (rsvg-convert,
#     ImageMagick and Pillow are all absent) and it only honours -s on a SQUARE
#     canvas. So every SVG here is authored square with the real artwork in a
#     centred band, and sips crops the band out afterwards.
#   * Backgrounds are vertical gradients, never diagonal and never with a radial
#     glow over the top. The renderer dithers gradients; a gradient that varies
#     along both axes leaves no two neighbouring pixels alike and PNG's per-row
#     filters have nothing to work with. The first cut of the social card was
#     490 KB that way and 55 KB as a vertical ramp. Some scrapers refuse files
#     over about 300 KB.
#   * png-rgb.py drops the alpha channel. Several social-card scrapers composite
#     alpha onto black, so og-cartworth.png in particular must not carry one.
set -euo pipefail

WHAT="${1:-all}"

HERE="$(cd "$(dirname "$0")" && pwd)"
SITE="$(cd "$HERE/.." && pwd)"
ROOT="$(cd "$SITE/.." && pwd)"
SRC="$HERE/src"
OUT="$SITE/img"
RGB="$HERE/png-rgb.py"
ICON="$ROOT/ios/App/Resources/Assets.xcassets/AppIcon.appiconset/AppIcon-1024.png"

TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT
mkdir -p "$OUT"

# raster <source.svg> <square size> <crop w> <crop h> <out.png>
raster() {
  local svg="$1" size="$2" cw="$3" ch="$4" out="$5"
  rm -f "$TMP/$(basename "$svg").png"
  qlmanage -t -s "$size" -o "$TMP" "$svg" >/dev/null 2>&1
  local raw="$TMP/$(basename "$svg").png"
  [ -f "$raw" ] || { echo "qlmanage produced nothing for $svg" >&2; exit 1; }
  sips -c "$ch" "$cw" "$raw" >/dev/null
  python3 "$RGB" "$raw" "$OUT/$out" --bg '#FFFFFF' >/dev/null
  rm -f "$raw"
}

if [ "$WHAT" = brand ] || [ "$WHAT" = all ]; then
  echo "== og-cartworth.png   1200x630 social card"
  raster "$SRC/og-cartworth.svg" 1200 1200 630 og-cartworth.png

  echo "== icon-180.png       apple-touch-icon"
  cp "$ICON" "$TMP/icon.png"; sips -z 180 180 "$TMP/icon.png" >/dev/null
  python3 "$RGB" "$TMP/icon.png" "$OUT/icon-180.png" >/dev/null

  echo "== cartworth-logo.png 512x512 Organization JSON-LD logo"
  cp "$ICON" "$TMP/logo.png"; sips -z 512 512 "$TMP/logo.png" >/dev/null
  python3 "$RGB" "$TMP/logo.png" "$OUT/cartworth-logo.png" >/dev/null
fi

if [ "$WHAT" = phones ] || [ "$WHAT" = all ]; then
  python3 "$HERE/make-phone-svg.py" >/dev/null
  echo "== iphone-max-search.png"
  raster "$SRC/phone-search.svg" 2322 1290 2322 iphone-max-search.png
  echo "== iphone-max-deal.png"
  raster "$SRC/phone-deal.svg"   2322 1290 2322 iphone-max-deal.png
  echo "== iphone-max-trip.png"
  raster "$SRC/phone-trip.svg"   2322 1290 2322 iphone-max-trip.png

  echo "== iphone-duo.png     1600x1000 two-up"
  python3 "$HERE/make-duo.py" "$TMP/duo.svg" >/dev/null
  raster "$TMP/duo.svg" 1600 1600 1000 iphone-duo.png
fi

echo
printf '%-24s %-12s %-6s %-7s %-6s %s\n' FILE SIZE SPP ALPHA SPACE BYTES
for f in og-cartworth.png icon-180.png cartworth-logo.png iphone-duo.png \
         iphone-max-search.png iphone-max-deal.png iphone-max-trip.png; do
  [ -f "$OUT/$f" ] || continue
  eval "$(sips -g pixelWidth -g pixelHeight -g samplesPerPixel -g hasAlpha -g space "$OUT/$f" 2>/dev/null \
          | awk -F': *' '/pixelWidth/{print "w="$2} /pixelHeight/{print "h="$2} /samplesPerPixel/{print "s="$2} /hasAlpha/{print "a="$2} /space/{print "c="$2}')"
  printf '%-24s %-12s %-6s %-7s %-6s %s\n' "$f" "${w}x${h}" "$s" "$a" "$c" "$(ls -l "$OUT/$f" | awk '{print $5}')"
done
